import json, pathlib
P=pathlib.Path(__file__).resolve().parent
industry=[
('Agriculture',2318549,-5.02,'Other'),('Mining',187647021,31.21,'Business / industrial'),('Utilities',134404529,84.10,'Business / industrial'),('Construction',228626065,17.78,'Business / industrial'),('Manufacturing',354688385,17.32,'Business / industrial'),('Wholesale Trade',411469024,15.41,'Business / industrial'),('Retail Trade',1572930560,3.01,'Consumer-facing'),('Transportation',56993453,9.83,'Mixed'),('Information',297638243,7.52,'Mixed'),('Finance and Insurance',33404507,12.19,'Mixed'),('Real Estate, Rental and Leasing',128284403,17.48,'Mixed'),('Services',473422344,13.78,'Mixed'),('Eating and Drinking Places',441750107,2.52,'Consumer-facing'),('Public Administration',20668400,3.29,'Other'),('No Code',62099175,185.69,'Unclassified')]
retail=[('Automotive Dealers',103838032,11.73),('Building Materials and Garden Equipment Stores',186098526,-1.27),('Clothing and Accessories Stores',130470023,3.99),('Electronic Shopping, Vending Machine, and Direct Sellers',304079153,-5.51),('Electronics and Appliances',75374377,16.24),('Food and Beverage Stores',138296262,-1.41),('Furniture and Home Furnishing Stores',56627701,-2.11),('Gasoline Stations',88431341,-0.39),('General Merchandise Stores',272090250,4.06),('Health and Personal Care Stores',27091873,4.78),('Miscellaneous Retail',137772300,25.25),('Sporting Goods, Hobby, Musical, and Book Stores',52740756,8.18)]
