html='''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Texas Sales Tax Monitor — Prototype</title><style>
:root{--bg:#f5f7fb;--ink:#17283d;--muted:#63758c;--accent:#1768ad;--line:#dfe6f0;--positive:#168061;--negative:#b23c48}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,Arial,sans-serif}.shell{max-width:1230px;padding:28px;margin:auto}h1{margin:0;font-size:30px;letter-spacing:-.7px}h2{font-size:18px;margin:0 0 8px}p{margin:4px 0;color:var(--muted)}.eyebrow{text-transform:uppercase;color:var(--accent);font-size:11px;letter-spacing:2px;font-weight:800}.hero{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:20px}.tag{background:#e6eff9;border:1px solid #cbd9e8;border-radius:12px;padding:9px 13px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:white;border:1px solid var(--line);border-radius:15px;padding:19px;box-shadow:0 3px 16px #1a355008}.kpi-label{color:var(--muted);font-size:12px}.kpi{font-size:27px;font-weight:750;margin:3px 0}.sub{font-size:12px;color:var(--muted)}.section{margin-top:18px}.cols{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}.controls{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}button,select,input{border:1px solid #cbd6e5;border-radius:8px;background:#fff;color:var(--ink);padding:9px 11px;font:inherit}button{cursor:pointer}button.selected{background:var(--accent);color:white;border-color:var(--accent)}.barrow{display:grid;grid-template-columns:180px 1fr 82px;gap:10px;align-items:center;margin:8px 0;font-size:12px}.track{background:#edf2f7;height:14px;border-radius:5px;overflow:hidden}.fill{background:var(--accent);height:100%;border-radius:5px}.growth{color:var(--positive)}.negative{color:var(--negative)}.scroll{max-height:500px;overflow:auto}.barlabel{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border-bottom:1px solid #edf0f4;text-align:left;padding:10px 8px}th{background:#f5f8fc;color:#526780;position:sticky;top:0;cursor:pointer}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}.note{background:#f2f6fb;border-left:3px solid #a8c2e1;padding:12px 15px;color:#53657a;font-size:13px;line-height:1.6}.links{display:flex;gap:15px;flex-wrap:wrap;margin-top:10px}a{color:var(--accent)}.disabled{opacity:.63}.status{font-size:12px;color:var(--muted)}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}.barrow{grid-template-columns:130px 1fr 65px}.hero{display:block}}@media(max-width:480px){.shell{padding:12px}.grid{grid-template-columns:1fr 1fr}.kpi{font-size:21px}.card{padding:12px}}
</style></head><body><main class="shell"><div class="hero"><div><div class="eyebrow">Economic & Fiscal Monitoring / Prototype v0.1</div><h1>Texas Sales Tax Monitor</h1><p>Industry receipts, retail subsectors, and foundations for local revenue nowcasting</p></div><div class="tag">VERIFIED SNAPSHOT · SEP 2026</div></div><div class="grid" id="kpis"></div><div class="section cols"><section class="card"><h2>Industry revenue composition</h2><p>Monthly taxpayer remittances by NAICS sector (nominal dollars)</p><div class="controls"><button class="selected" data-bar="dollars">Receipts</button><button data-bar="growth">Year-over-year growth</button><button data-bar="contrib">Contribution to growth</button></div><div class="scroll" id="bars"></div></section><section class="card"><h2>Retail vs. business-related activity</h2><p>Analytical groupings (not official consumption classifications)</p><div id="groupings"></div><div class="note" style="margin-top:18px">Industry classification is based on the taxpayer's primary NAICS code. It does <b>not</b> directly separate final household consumption from intermediate business purchases. Mixed industries are shown separately.</div></section></div><div class="section card"><h2>Detailed sector explorer</h2><p>Click column headers to sort. Retail subsectors overlap with the Retail Trade industry; do not sum industry and retail tables together.</p><div class="controls"><button class="selected" data-tab="industry">All industries</button><button data-tab="retail">Retail subsectors</button><input id="search" placeholder="Find an industry or subsector..." aria-label="Search industries" style="flex:1;min-width:210px"></div><div class="scroll"><table><thead><tr><th data-sort="name">Industry / subsector ↕</th><th class="num" data-sort="receipts">Receipts ↕</th><th class="num" data-sort="yoy">YoY ↕</th><th class="num" data-sort="delta">Est. change vs year ago ↕</th></tr></thead><tbody id="rows"></tbody></table></div></div><div class="section cols"><section class="card"><h2>City & county explorer</h2><div class="tag" style="display:inline-block;margin:10px 0">DATA PIPELINE INCLUDED · NOT LOADED IN THIS SNAPSHOT</div><p>Monthly city allocations by county are publicly available from Texas Open Data. The included <code>fetch_local.py</code> script retrieves them; this static prototype deliberately does not invent local values.</p><div class="links"><a target="_blank" href="https://data.texas.gov/Government-and-Taxes/Sales-Tax-Allocation-City-County-Comparison-Summar/53pa-m7sm">View source</a></div></section><section class="card"><h2>Forecasting roadmap</h2><p>Next: vintage-aware historical series and a seasonal baseline; then employment, prices, construction, energy, and other leading indicators.</p><div class="note" style="margin-top:14px">No model or forecast has been estimated yet. Observed YoY changes are not forecasts.</div></section></div><div class="section card"><h2>Methods, definitions & sources</h2><div class="note">Official statewide NAICS series reflect taxpayer-account postings and may be revised. They can differ from Treasury cash-deposit figures. The Sept 2026 retail-subsector total differs slightly from the retail industry total; both are preserved as published. Estimates of the dollar change vs year ago are reconstructed from published rounded percentage changes and are therefore <b>approximate</b>. The classifications 'business / industrial' and 'consumer-facing' are initial analytical groupings, not official data fields.</div><div class="links"><a href="https://comptroller.texas.gov/transparency/revenue/watch/naics/naics-industry.php" target="_blank">Industry source</a><a href="https://comptroller.texas.gov/transparency/revenue/watch/naics/naics-retail.php" target="_blank">Retail source</a><a href="https://comptroller.texas.gov/transparency/revenue/watch/all-funds/" target="_blank">Revenue Watch</a><a href="https://data.texas.gov/d/53pa-m7sm" target="_blank">Local allocations</a></div><p class="status" style="margin-top:10px">Data: September 2026; local source last observed October 7, 2026. Not an official Texas Comptroller product.</p></div></main><script>
const D=__DATA__;let tab='industry',bar='dollars',sortBy='receipts',sortDir=-1;const fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n), compact=n=>n>=1e9?'$'+(n/1e9).toFixed(2)+'B':n>=1e6?'$'+(n/1e6).toFixed(1)+'M':fmt(n),rate=x=>(x>=0?'+':'')+x.toFixed(2)+'%',delta=x=>x.receipts*x.yoy/(100+x.yoy);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const top=[['NAICS industry receipts',compact(D.industry_reported_total),'September 2026'],['Reported NAICS YoY growth','+11.42%','September 2026'],['Retail trade receipts',compact(D.industry.find(x=>x.name==='Retail Trade').receipts),'Retail NAICS industry'],['Treasury cash sales tax',compact(D.state_cash_october),'October 2026 · different basis / month']];document.getElementById('kpis').innerHTML=top.map(x=>`<div class="card"><div class="kpi-label">${x[0]}</div><div class="kpi">${x[1]}</div><div class="sub">${x[2]}</div></div>`).join('');
function renderBars(){let a=[...D.industry];let score=x=>bar==='growth'?x.yoy:bar==='contrib'?delta(x):x.receipts;a.sort((x,y)=>score(y)-score(x));let m=Math.max(...a.map(x=>Math.abs(score(x))));document.getElementById('bars').innerHTML=a.map(x=>{let v=score(x),w=Math.max(1,Math.abs(v)/m*100),t=bar==='growth'?rate(v):compact(v);return `<div class="barrow"><span class="barlabel" title="${esc(x.name)}">${esc(x.name)}</span><div class="track"><div class="fill" style="width:${w}%;background:${v<0?'#b23c48':'#1768ad'}"></div></div><b class="num">${t}</b></div>`}).join('')}
function renderGroups(){let types=['Business / industrial','Consumer-facing','Mixed','Other','Unclassified'];let sums=types.map(t=>({name:t,value:D.industry.filter(x=>x.group===t).reduce((a,x)=>a+x.receipts,0)}));let total=sums.reduce((a,x)=>a+x.value,0);let colors=['#b97636','#1768ad','#7192ac','#8b9dad','#b5beca'];document.getElementById('groupings').innerHTML=`<div style="height:23px;display:flex;border-radius:6px;overflow:hidden;margin:24px 0">${sums.map((x,i)=>`<div style="width:${x.value/total*100}%;background:${colors[i]}" title="${x.name}: ${compact(x.value)}"></div>`).join('')}</div>`+sums.map((x,i)=>`<div style="display:flex;align-items:center;justify-content:space-between;margin:13px 0;gap:8px"><span><span style="background:${colors[i]};display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:8px"></span>${x.name}</span><b>${(100*x.value/total).toFixed(1)}%</b></div>`).join('')}
function renderRows(){let a=[...D[tab]].filter(x=>x.name.toLowerCase().includes(document.getElementById('search').value.toLowerCase()));a.sort((x,y)=>{let va=sortBy==='delta'?delta(x):x[sortBy],vb=sortBy==='delta'?delta(y):y[sortBy];return sortDir*(typeof va==='string'?va.localeCompare(vb):va-vb)});document.getElementById('rows').innerHTML=a.map(x=>`<tr><td>${esc(x.name)}${x.group?`<div class="sub">${esc(x.group)}</div>`:''}</td><td class="num">${fmt(x.receipts)}</td><td class="num ${x.yoy<0?'negative':'growth'}">${rate(x.yoy)}</td><td class="num ${delta(x)<0?'negative':'growth'}">${compact(delta(x))}</td></tr>`).join('')||'<tr><td colspan="4">No matching sectors.</td></tr>'}
document.querySelectorAll('[data-bar]').forEach(b=>b.onclick=()=>{bar=b.dataset.bar;document.querySelectorAll('[data-bar]').forEach(n=>n.classList.toggle('selected',n===b));renderBars()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('selected',n===b));renderRows()});document.getElementById('search').oninput=renderRows;document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(sortBy===b.dataset.sort)sortDir*=-1;else{sortBy=b.dataset.sort;sortDir=b.dataset.sort==='name'?1:-1}renderRows()});renderBars();renderGroups();renderRows();</script></body></html>'''
(P/'index.html').write_text(html.replace('__DATA__',json.dumps(data)))
print('Built',P/'index.html')
